            {"it": "«Es más lento que una tortuga»", "cat": "comparacion",
             "m": "'Más… que' compara."},
            {"it": "«El otoño es una carta amarilla»", "cat": "metafora",
             "m": "Sustituye una cosa por otra."},
            {"it": "«Las hojas susurraban un secreto»", "cat": "personificacion",
             "m": "Susurrar un secreto lo hace alguien que habla."},
            {"it": "«Duro como una piedra»", "cat": "comparacion",
             "m": "'Como' otra vez: comparación."},
            {"it": "«Sus manos eran dos pájaros nerviosos»", "cat": "metafora",
             "m": "Las manos SON pájaros: reemplazo, no comparación."},
            {"it": "«El sol se despertó temprano»", "cat": "personificacion",
             "m": "Despertarse es de un ser vivo."},
            {"it": "«Tan callado como un ratón»", "cat": "comparacion",
             "m": "El 'tan… como' es la marca."},
            {"it": "«La noche es un manto negro»", "cat": "metafora",
             "m": "La noche ES el manto, sin 'como'."},
