    # Nueve de los dieciocho temas. Cinco van PARAMÉTRICAS porque la auditoría las
    # marca con ⚙: un banco fijo de 20 ítems se memoriza en dos partidas
    # ([[ct3d-memorizacion-bancos]]), y estos temas son justo los que el chico
    # repasa en ráfaga antes de una prueba.
    {
        "id": "romanos_5", "grado": 5, "area": "matematica",
        "titulo": "Traductor romano", "icono": "🏛️",
        "mecanica": "trivia",
        "consigna": "¿Cuánto vale?",
        "dc": "Sistema romano: diferencias con el decimal (posicionalidad, el cero)",
        "fuente": "docs/auditoria-dc-caba/grado-5.md · M2",
        "saber": {"id": "MAT-5-romanos", "nombre": "Sistema de numeración romano",
                  "prereqs": []},
        "banco": [
            {"q": "¿Cuánto vale V?", "ops": ["5", "4", "10"],
             "m": "Las letras base: I=1, V=5, X=10, L=50, C=100, D=500, M=1000."},
            {"q": "¿Cuánto vale XV?", "ops": ["15", "5", "51"],
             "m": "X (10) + V (5). Cuando la letra menor va DESPUÉS, se suma."},
            {"q": "¿Cuánto vale IX?", "ops": ["9", "11", "10"],
             "m": "La I ADELANTE de la X resta: 10 − 1 = 9. Ésa es la regla sustractiva."},
            {"q": "¿Cuánto vale XI?", "ops": ["11", "9", "10"],
             "m": "Ahora la I va después: se suma. XI = 11, IX = 9. El orden cambia todo."},
            {"q": "¿Cuánto vale XL?", "ops": ["40", "60", "410"],
             "m": "X delante de L resta: 50 − 10 = 40."},
            {"q": "¿Cuánto vale LX?", "ops": ["60", "40", "510"],
             "m": "Ahora se suma: 50 + 10."},
            {"q": "¿Cuánto vale CM?", "ops": ["900", "1100", "100000"],
             "m": "C delante de M resta: 1000 − 100 = 900."},
            {"q": "¿Cuánto vale MC?", "ops": ["1100", "900", "1000100"],
             "m": "Se suma: 1000 + 100."},
            {"q": "¿Cómo se escribe 14?", "ops": ["XIV", "XIIII", "VIX"],
             "m": "10 + 4, y el 4 es IV. No se repite una letra más de tres veces."},
            {"q": "¿Cómo se escribe 2026?", "ops": ["MMXXVI", "MMXXVV", "MXXVI"],
             "m": "1000+1000+10+10+5+1."},
            {"q": "¿Cuánto vale XXIX?", "ops": ["29", "31", "21"],
             "m": "XX (20) + IX (9)."},
            {"q": "¿Cómo se escribe 90?", "ops": ["XC", "LXXXX", "CX"],
             "m": "100 − 10. No se escriben cuatro X seguidas."},
            {"q": "¿Cuál es la diferencia más grande con nuestro sistema?",
             "ops": ["El romano no tiene cero", "El romano usa más números",
                     "El romano se lee al revés"],
             "m": "No hay símbolo para el cero, y por eso tampoco hay valor posicional: "
                  "en 'XX' las dos equis valen lo mismo, en '22' los dos doses no."},
            {"q": "En el número 55, ¿los dos cincos valen lo mismo?",
             "ops": ["No: uno vale 50 y el otro 5", "Sí, los dos valen 5",
                     "Sí, los dos valen 50"],
             "m": "Eso es el valor posicional, y el sistema romano no lo tiene."},
            {"q": "¿Cuánto vale MMXIV?", "ops": ["2014", "2016", "2024"],
             "m": "2000 + 10 + 4."},
            {"q": "¿Se puede escribir el cero en números romanos?",
             "ops": ["No existe símbolo para el cero", "Sí, es la O",
                     "Sí, es la N"],
             "m": "Es la gran limitación del sistema: sin cero, hacer cuentas escritas es "
                  "durísimo."},
            {"q": "¿Cuánto vale XLIV?", "ops": ["44", "56", "64"],
             "m": "XL (40) + IV (4)."},
            {"q": "¿Cómo se escribe 400?", "ops": ["CD", "CCCC", "DC"],
             "m": "500 − 100. DC sería 600."},
        ],
    },
