    {"id":"bucle_2","grado":2,"area":"logica","titulo":"El bucle","icono":"🔁",
     "mecanica":"trivia","consigna":"¿Qué hace el programa?",
     "dc":"Repetir: contar repeticiones frente a contar bloques",
     "fuente":"docs/auditoria-dc-caba/grado-2.md · T2",
     "saber":{"id":"TEC-2-bucle","nombre":"Bucles","prereqs":[]},
     "banco":[
      {"q":"«repetir 3 veces: avanzar». ¿Cuántos casilleros avanza?","ops":["3","1","0"],
       "m":"El bloque de adentro se hace 3 veces."},
      {"q":"«repetir 4 veces: avanzar, girar». ¿Cuántas veces gira?","ops":["4","1","8"],
       "m":"Todo lo de adentro se repite: gira 4 veces."},
      {"q":"En «repetir 4 veces: avanzar, girar», ¿cuántos BLOQUES hay adentro?",
       "ops":["2","4","8"],
       "m":"Ojo: 2 bloques que se hacen 4 veces. No es lo mismo contar bloques que repeticiones."},
      {"q":"«avanzar, avanzar, avanzar» se puede escribir como…",
       "ops":["repetir 3 veces: avanzar","repetir 1 vez: avanzar","avanzar 3"],
       "m":"El bucle acorta lo repetido."},
      {"q":"¿Para qué sirve el bloque repetir?","ops":["Para no copiar lo mismo muchas veces",
       "Para que ande más rápido","Para borrar"],"m":"Hace el programa más corto y claro."},
      {"q":"«repetir 2 veces: avanzar, avanzar». ¿Cuánto avanza en total?","ops":["4","2","1"],
       "m":"2 avances × 2 repeticiones."},
      {"q":"Si el robot tiene que dar la vuelta a un cuadrado, ¿cuántas veces repite?",
       "ops":["4","1","2"],"m":"Un cuadrado tiene 4 lados."},
      {"q":"«repetir 5 veces: saltar». ¿Cuántos saltos?","ops":["5","1","10"],"m":"Cinco."},
      {"q":"¿Se puede poner un repetir adentro de otro repetir?","ops":["Sí","No",
       "Sólo dos veces"],"m":"Se llama bucle anidado."},
      {"q":"«repetir 3 veces: avanzar» y después «avanzar». ¿Cuánto avanzó?",
       "ops":["4","3","1"],"m":"3 del bucle más 1 suelto."},
      {"q":"Si te equivocaste en el número de repeticiones, ¿qué cambiás?",
       "ops":["Sólo el número","Todo el programa","Los bloques de adentro"],
       "m":"Un cambio chico arregla un error chico."},
      {"q":"¿El bucle cambia lo que hace el programa?",
       "ops":["No, sólo lo escribe más corto","Sí, hace otra cosa","Lo hace más lento"],
       "m":"El resultado es el mismo."}]},
    {"id":"condicional_2","grado":2,"area":"logica","titulo":"Si pasa esto…","icono":"🔀",
     "mecanica":"trivia","consigna":"¿Qué hace el robot?",
     "dc":"Condicionales simples",
     "fuente":"docs/auditoria-dc-caba/grado-2.md · T3",
     "saber":{"id":"TEC-2-condicional","nombre":"Condicionales","prereqs":["TEC-2-bucle"]},
     "banco":[
      {"q":"«SI hay pared, ENTONCES girar». Hay pared. ¿Qué hace?","ops":["Gira","Avanza",
       "Nada"],"m":"Se cumple la condición."},
      {"q":"Con esa misma regla: NO hay pared. ¿Qué hace?","ops":["No gira","Gira","Se apaga"],
       "m":"Si la condición no se cumple, no hace la acción."},
      {"q":"«SI está oscuro, ENTONCES prender la luz». Es de día. ¿Qué pasa?",
       "ops":["No se prende","Se prende","Se apaga"],"m":"No está oscuro."},
      {"q":"¿Qué parte de la regla es «SI hay pared»?","ops":["La condición","La acción",
       "El resultado"],"m":"Es lo que se pregunta."},
      {"q":"¿Y «ENTONCES girar»?","ops":["La acción","La condición","El error"],
       "m":"Es lo que se hace si se cumple."},
      {"q":"«SI hay moneda, ENTONCES sumar 1 punto». Pasa por 3 monedas. ¿Cuántos puntos?",
       "ops":["3","1","0"],"m":"La regla se aplica cada vez."},
      {"q":"«SI llueve, ENTONCES llevar paraguas». No llueve. ¿Lleva paraguas?",
       "ops":["No","Sí","A veces"],"m":"La condición manda."},
      {"q":"¿Se puede tener dos condiciones juntas?","ops":["Sí, con un Y","No","Sólo con un O"],
       "m":"«SI está oscuro Y hay movimiento»."},
      {"q":"«SI está oscuro Y hay alguien, prender». Está oscuro pero no hay nadie.",
       "ops":["No prende","Prende","Prende a la mitad"],"m":"Con Y tienen que cumplirse las dos."},
      {"q":"¿Para qué sirve un condicional?","ops":["Para que el programa decida",
       "Para repetir","Para borrar"],"m":"Permite que actúe distinto según lo que pasa."},
      {"q":"«SI toca el borde, ENTONCES rebotar». Está en el medio. ¿Rebota?",
       "ops":["No","Sí","Se detiene"],"m":"No tocó el borde."},
      {"q":"En un juego, «si las vidas llegan a 0, terminar» es…","ops":["Un condicional",
       "Un bucle","Una variable"],"m":"Decide según una condición."}]},
