      {"q":"Un compañero se queda solo en el recreo. ¿Qué podés hacer?",
       "ops":["Invitarlo a jugar","Ignorarlo","Reírte"],"m":"Incluir cuesta poco y cambia el día."},
      {"q":"¿Para qué sirven los acuerdos del aula?","ops":["Para que todos puedan estar bien",
       "Para castigar","Para que mande uno"],"m":"Son reglas que se acuerdan entre todos."},
