    {"id":"armar_calculo_1","grado":1,"area":"matematica","titulo":"Armá el cálculo","icono":"➕",
     "mecanica":"trivia","consigna":"¿Qué cuenta resuelve el problema?",
     "dc":"Componer el cálculo que resuelve el problema",
     "fuente":"docs/auditoria-dc-caba/grado-1.md · M8",
     "saber":{"id":"MAT-1-calculo","nombre":"Elegir el cálculo","prereqs":[]},
     "banco":[
      {"q":"Tenía 5 figuritas y le dieron 3. ¿Qué cuenta hacés?","ops":["5 + 3","5 − 3","3 − 5"],
       "m":"Le dieron más: se suma."},
      {"q":"Tenía 8 caramelos y comió 2. ¿Qué cuenta?","ops":["8 − 2","8 + 2","2 − 8"],
       "m":"Comió: se quita."},
      {"q":"Hay 4 nenes y llegan 2 más. ¿Qué cuenta?","ops":["4 + 2","4 − 2","2 − 4"],
       "m":"Llegan más: se suma."},
      {"q":"Tenía 10 globos y se le escaparon 3. ¿Qué cuenta?","ops":["10 − 3","10 + 3","3 − 10"],
       "m":"Se escaparon: se resta."},
      {"q":"Junté 6 piedritas y después 4 más. ¿Qué cuenta?","ops":["6 + 4","6 − 4","4 − 6"],
       "m":"Junté más."},
      {"q":"En el colectivo había 9 y bajaron 5. ¿Qué cuenta?","ops":["9 − 5","9 + 5","5 − 9"],
       "m":"Bajaron: quedan menos."},
      {"q":"Tenía 7 y ahora tiene 10. ¿Cuántos le dieron?","ops":["10 − 7","10 + 7","7 − 10"],
       "m":"Para saber cuánto se agregó, se resta."},
      {"q":"Hay 3 en una caja y 5 en otra. ¿Cuántos hay?","ops":["3 + 5","5 − 3","3 − 5"],
       "m":"Se juntan las dos cajas."},
      {"q":"Tenía 12 y regaló 4. ¿Qué cuenta?","ops":["12 − 4","12 + 4","4 − 12"],
       "m":"Regaló: se va."},
      {"q":"«Le dieron», «llegaron», «juntó» son palabras de…","ops":["Sumar","Restar",
       "Ninguna"],"m":"Todas indican que hay más."},
      {"q":"«Comió», «perdió», «bajaron» son palabras de…","ops":["Restar","Sumar",
       "Ninguna"],"m":"Todas indican que hay menos."},
      {"q":"Tenía 6, le dieron 2 y perdió 1. ¿Cuántas cuentas hacés?","ops":["Dos","Una",
       "Ninguna"],"m":"Primero sumás y después restás."}]},
