    {"id":"cuidarnos_1","grado":1,"area":"cdm","titulo":"Cuidarnos","icono":"💚",
     "mecanica":"trivia","consigna":"¿Qué conviene hacer?",
     "dc":"Cuidado del cuerpo; a quién acudir",
     "fuente":"docs/auditoria-dc-caba/grado-1.md · C8",
     "saber":{"id":"CDM-1-cuidarnos","nombre":"Cuidado del cuerpo","prereqs":[]},
     "banco":[
      {"q":"Antes de comer conviene…","ops":["Lavarse las manos","Correr","Mirar la tele"],
       "m":"Las manos traen microbios que no se ven."},
      {"q":"Si te sentís mal, ¿a quién le avisás?","ops":["A un adulto de confianza",
       "A nadie","Al que pase"],"m":"Contarlo es lo que te ayuda."},
      {"q":"¿Cuántas veces por día conviene lavarse los dientes?","ops":["Después de cada comida",
       "Una vez por semana","Nunca"],"m":"Sobre todo antes de dormir."},
      {"q":"Jugar sin parar todo el día es…","ops":["Demasiado: también hay que descansar",
       "Perfecto","Obligatorio"],"m":"Jugar está buenísimo, y dormir también hace falta."},
      {"q":"¿Cuántas horas conviene dormir a tu edad?","ops":["Unas 10","3","20"],
       "m":"Dormir es cuando el cuerpo crece y descansa."},
      {"q":"Si te lastimás en el recreo, ¿qué hacés?","ops":["Avisás a la maestra",
       "Seguís jugando","Te escondés"],"m":"Un adulto puede curarte."},
      {"q":"¿Para qué sirve tomar agua?","ops":["El cuerpo la necesita todo el día",
       "Sólo si hace calor","Para nada"],"m":"Es lo que más conviene tomar."},
      {"q":"Si alguien te toca y no te gusta, ¿qué hacés?","ops":["Decís que no y avisás a un adulto",
       "Te callás","Te vas sin decir nada"],
       "m":"Tu cuerpo es tuyo. Decir que no está bien, y contarlo también."},
      {"q":"¿Quién puede ayudarte en la escuela?","ops":["La maestra o la directora",
       "Nadie","Sólo tu mamá"],"m":"Hay adultos a cargo de cuidarte ahí también."},
      {"q":"¿Hay que hacer actividad física?","ops":["Sí, jugar y moverse hace bien",
       "No","Sólo los grandes"],"m":"Correr y saltar también es cuidarse."},
      {"q":"Si un compañero se lastima, ¿qué hacés?","ops":["Avisás a un adulto",
       "Te reís","No hacés nada"],"m":"Avisar ya es ayudar."},
      {"q":"¿Para qué sirve ir al médico si no estás enfermo?","ops":["Para controlar que estés bien",
       "Para nada","Sólo para las vacunas"],"m":"El control evita problemas."}]},
