    {"id":"planta_partes_1","grado":1,"area":"cdm","titulo":"Armá la planta","icono":"🌿",
     "mecanica":"trivia","consigna":"¿Para qué sirve cada parte?",
     "dc":"Partes de la planta y su función",
     "fuente":"docs/auditoria-dc-caba/grado-1.md · C2",
     "saber":{"id":"CDM-1-planta","nombre":"Partes de la planta","prereqs":[]},
     "banco":[
      {"q":"¿Qué parte de la planta toma el agua de la tierra?","ops":["La raíz","La hoja","La flor"],
       "m":"La raíz está abajo, en la tierra, y chupa el agua."},
      {"q":"¿Qué parte sostiene la planta y lleva el agua para arriba?","ops":["El tallo","La raíz","El fruto"],
       "m":"El tallo es como una cañita por donde sube el agua."},
      {"q":"¿En qué parte la planta fabrica su alimento?","ops":["Las hojas","La raíz","El tallo"],
       "m":"Las hojas usan la luz del sol para eso."},
      {"q":"¿Qué parte se abre de colores para atraer insectos?","ops":["La flor","La raíz","El tallo"],
       "m":"La flor llama a los insectos que la ayudan."},
      {"q":"¿Dónde están las semillas?","ops":["Adentro del fruto","En la raíz","En el tallo"],
       "m":"El fruto guarda las semillas."},
      {"q":"Si le cortás las raíces a una planta, ¿qué pasa?","ops":["No puede tomar agua","Crece más",
       "No pasa nada"],"m":"Sin raíz no llega el agua."},
      {"q":"Si la ponés en un lugar totalmente oscuro, ¿qué pasa?","ops":["No puede fabricar su alimento",
       "Crece igual","Se pone verde"],"m":"Las hojas necesitan luz."},
      {"q":"¿Qué necesita una planta para vivir?","ops":["Agua, luz, aire y tierra","Sólo agua",
       "Sólo luz"],"m":"Las cuatro cosas."},
      {"q":"La zanahoria que comemos es…","ops":["Una raíz","Un fruto","Una flor"],
       "m":"Es la raíz de la planta."},
      {"q":"La lechuga que comemos es…","ops":["Hojas","Raíz","Fruto"],"m":"Son las hojas."},
      {"q":"El tomate que comemos es…","ops":["Un fruto","Una raíz","Una hoja"],
       "m":"Tiene semillas adentro: es fruto."},
      {"q":"¿De dónde sale una planta nueva?","ops":["De una semilla","De una hoja suelta",
       "De la nada"],"m":"La semilla trae adentro la planta chiquita."}]},
